        and (
            n.network_name like concat('%', #{keyword}, '%')
            or n.police_station_name like concat('%', #{keyword}, '%')
            or n.start_ip like concat('%', #{keyword}, '%')
            or n.end_ip like concat('%', #{keyword}, '%')
            or ns.gateway_ip like concat('%', #{keyword}, '%')
            or exists (
                select 1
                from ipam_address search_address
                where search_address.network_id = n.network_id
                  and (
                      search_address.community_name like concat('%', #{keyword}, '%')
                      or search_address.ip_address = #{keyword}
                      or search_address.internal_ip_address = #{keyword}
                  )
            )
            or (
                inet_ntoa(inet_aton(#{keyword})) = #{keyword}
                and inet_aton(#{keyword}) between inet_aton(n.start_ip) and inet_aton(n.end_ip)
            )
        )

    and n.status = #{status}
    and trim(n.police_station_name) = #{policeStationName}

order by case when ns.gateway_ip is null or ns.gateway_ip = '' then 1 else 0 end,
         inet_aton(ns.gateway_ip),
         inet_aton(n.start_ip),
         n.network_id


where n.start_value <= #{endValue}
  and n.end_value >= #{startValue}
and n.network_id != #{excludeNetworkId}
order by n.start_value, n.network_id
limit 1

mapper.update:
update ipam_network
set scenario_type = #{scenarioType},
    update_by = #{username},
    update_time = #{now}
where scenario_type is null or scenario_type != #{scenarioType}

update ipam_segment
segment_name = #{segmentName}, cidr_block = #{cidrBlock}, start_ip = #{startIp}, end_ip = #{endIp}, gateway_ip = #{gatewayIp}, prefix_length = #{prefixLength}, total_count = #{totalCount}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where segment_id = #{segmentId}

update ipam_network
network_name = #{networkName}, police_station_name = #{policeStationName}, cidr_block = #{cidrBlock}, start_ip = #{startIp}, end_ip = #{endIp}, start_value = #{startValue}, end_value = #{endValue}, prefix_length = #{prefixLength}, scenario_type = #{scenarioType}, status = #{status}, update_by = #{updateBy}, update_time = #{updateTime}, remark = #{remark},
where network_id = #{networkId}

