    and a.network_id = #{networkId}
    and a.segment_id = #{segmentId}
    and a.ip_address like concat('%', #{ipAddress}, '%')
    and a.status = #{status}
    and a.status <> 'FREE'
    and a.community_name like concat('%', #{communityName}, '%')
    and a.target_type = #{targetType}
    and a.target_name like concat('%', #{targetName}, '%')
    and a.manufacturer = #{manufacturer}
    and a.internal_ip_address like concat('%', #{internalIpAddress}, '%')
    and a.access_unit like concat('%', #{accessUnit}, '%')

order by a.ip_value


where a.segment_id = #{segmentId}
  and a.ip_value between #{startValue} and #{endValue}
order by a.ip_value

select ifnull(nullif(trim(a.community_name), ''), '未填写名称') as community_name, count(1) as address_count, sum(case when nullif(trim(a.target_type), '') is not null or nullif(trim(a.target_name), '') is not null then 1 else 0 end) as device_count, substring_index(group_concat(a.ip_address order by a.ip_value separator ','), ',', 1) as first_ip, substring_index(group_concat(a.ip_address order by a.ip_value desc separator ','), ',', 1) as last_ip, group_concat(distinct nullif(a.internal_ip_address, '') order by a.internal_ip_address separator '、') as internal_ip_summary, group_concat(distinct nullif(a.target_type, '') order by a.target_type separator '、') as target_type_summary, group_concat(distinct nullif(a.manufacturer, '') order by a.manufacturer separator '、') as manufacturer_summary, group_concat(distinct nullif(a.access_unit, '') order by a.access_unit separator '、') as access_unit_summary, group_concat(distinct nullif(a.owner_name, '') order by a.owner_name separator '、') as owner_summary, group_concat(distinct nullif(concat_ws(' ', a.mapping_address, a.mapping_port, a.mapping_description), '') order by a.mapping_address separator '、') as mapping_summary from ipam_address a where a.status in ('ALLOCATED', 'ISSUED') and a.network_id = #{networkId} and a.segment_id = #{segmentId} and a.target_type = #{targetType} and a.manufacturer = #{manufacturer}
and ( a.community_name like concat('%', #{keyword}, '%') or a.ip_address like concat('%', #{keyword}, '%') or a.internal_ip_address like concat('%', #{keyword}, '%') or a.target_name like concat('%', #{keyword}, '%') or a.target_type like concat('%', #{keyword}, '%') or a.manufacturer like concat('%', #{keyword}, '%') or a.access_unit like concat('%', #{keyword}, '%') or a.owner_name like concat('%', #{keyword}, '%') or a.mapping_address like concat('%', #{keyword}, '%') or a.mapping_port like concat('%', #{keyword}, '%') or a.mapping_description like concat('%', #{keyword}, '%') )
group by ifnull(nullif(trim(a.community_name), ''), '未填写名称') order by min(a.ip_value)
